/*updateMasterCmClIndividual*/

		UPDATE
		    ICOMGRDT GR /* 구매사별 입고정보 */
		SET



			AR_CLOSE_DEPT = LPAD( #{KEP_DEPT}, 3, 0 ),




			GR_DATE = #{GR_DATE},



		    STATUS = 'R'
		WHERE 1=1
		AND BUYER = #{BUYER}
		AND GR_NO = #{GR_NO}
		AND GR_SEQ = #{GR_SEQ}

/*insertMasterCmClIndividual_KEPTARDT*/
INSERT INTO KEPTARDT /* 외상매출_세금계산서 */ ( TAX_BILL_NO , KEP_IRS , SITE , DEPT_CODE , STATUS , ISSUE_DATE , CUSTOMER_NAME , IRS_NO , BUYER_CODE
, TOT_SUPP_PRICE , TOT_TAX_PRICE , TOT_AMT , SUPP_PRICE , TAX_PRICE , AMT
, TAX_TYPE , BILL_TYPE , PRINT_DATE , PRINT_USER_ID , PRINT_CNT , PRINT_AVAIL_CNT , CONFIRM_FLAG , REMARK_DESCRIPTION , REMARK_SPECIFICATION , REMARK_QTY , REMARK_PRICE
, ASK_TYPE , ADD_DATE , ADD_TIME , ADD_USER_ID , CHANGE_DATE , CHANGE_TIME , CHANGE_USER_ID
, AR_CLOSE_MONTH , AR_CLOSE_REVISION , KEP_IRS_NAME , KEP_CEO_NAME_LOC , KEP_INDUSTRY_TYPE , KEP_BUSINESS_ITEMS , KEP_ADDRESS_LOC , IRS_NAME , CEO_NAME_LOC , INDUSTRY_TYPE , BUSINESS_ITEMS , ADDRESS_LOC ) VALUES ( #{order_no} , #{KEP_IRS_NO} , DECODE(#{BUYER}, 'KRKOLO0077', 'KK','KA') , #{dept_code} , 'C' , #{issue_date} || #{issue_last_day} , #{BUYER_NAME} , #{BUYER_IRS_NO} , #{BUYER}
, TRUNC(#{tot_amt}) , DECODE(#{TAX_TYPE}, '12', 0, TRUNC(#{tot_amt} * 0.1)) , TRUNC(#{tot_amt}) + DECODE(#{TAX_TYPE}, '12', 0, TRUNC(#{tot_amt} * 0.1)) , TRUNC(#{supp_price}) /*SUPP_PRICE*/ , DECODE(#{TAX_TYPE}, '12', 0, TRUNC(#{tax_price})) /*TAX_PRICE*/ , TRUNC(#{supp_price}) + DECODE(#{TAX_TYPE}, '12', 0, TRUNC(#{tax_price})) /*AMT*/
, DECODE(#{TAX_TYPE}, '12', '13', '11') /*TAX_TYPE*/ , (SELECT BILL_TYPE FROM V_VOC_ICOMCMPY WHERE SYS_TYPE IN ('KA', 'KK') AND LPAD(COM_CODE,10,0) = #{BUYER} AND BUSINESS_COND <> 'S') /*BILL_TYPE*/ , '' /*PRINT_DATE*/ , '' /*PRINT_USER_ID*/ , 0 /*PRINT_CNT*/ , 1 /*PRINT_AVAIL_CNT*/ , 'N' /*CONFIRM_FLAG*/ , 'MRO용품외' , 'MRO용품외' , 1 , #{tot_amt}
, '02' /*ASK_TYPE*/ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id} , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id}
, #{issue_date} , #{st_close_revision} , #{kep_irs_name} , #{kep_ceo_name_loc} , #{kep_industry_type} , #{kep_business_items} , #{kep_address_loc} , #{buyer_irs_name} , #{buyer_ceo_name_loc} , #{buyer_industry_type} , #{buyer_business_items} , #{buyer_address_loc} )

/*updateMasterCmClIndividual_ICOMGRDT*/

		UPDATE 
		    ICOMGRDT /* 구매사별 입고정보 */
		SET
		    AR_TAX_BILL_NO      = #{order_no}
		  , AR_CLOSE_DEPT       = LPAD(#{dept_code},3,0)
		  , AR_CLOSE_MONTH      = #{issue_date}
		  , AR_CLOSE_REVISION   = #{st_close_revision}
		  , AR_BILL_FLAG        = 'Y'
		  , CLOSE_USER_ID       = DECODE(CLOSE_USER_ID,NULL,#{st_user_id},CLOSE_USER_ID)
		WHERE 1=1
		AND BUYER  = #{key_buyer}
		AND GR_NO  = #{key_gr_no}
		AND GR_SEQ = #{key_gr_seq}
		AND STATUS <> 'D'

