/*selectIcomgrdtDelYn*/

		SELECT DECODE(STATUS, 'D', 'Y', 'N') AS DelYn
		FROM ICOMGRDT
		WHERE BUYER = #{BUYER}
		AND GR_NO = #{GR_NO}
		AND GR_SEQ = #{GR_SEQ}

