/* updateDDateIv_v2 */
UPDATE	ICOMIVDT IVDT
SET		IVDT.DELIVERY_DATE = #{GR_DATE},
		IVDT.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
		IVDT.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE	IVDT.BUYER = #{BUYER}
AND		IVDT.INV_NO = #{INV_NO}
AND		IVDT.INV_SEQ = #{INV_SEQ}
AND		IVDT.STATUS <> 'D'


/* updateDDateIvWms_v2 */
UPDATE	ICOMIVDT IVDT
SET		DELIVERY_DATE = #{GR_DATE},
		CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
		CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE	(BUYER,INV_NO,INV_SEQ) = (
	SELECT BUYER,S_INV_NO,S_INV_SEQ FROM WMSIVDT WMS
	WHERE	WMS.BUYER = #{BUYER}
	AND		WMS.INV_NO = #{INV_NO}
	AND		WMS.INV_SEQ = #{INV_SEQ}
	AND		WMS.STATUS <> 'D'
)
AND		IVDT.STATUS <> 'D'
